def spaced_picks(values, gap):
    out, pick = [], []

    def walk(start):
        for i in range(start, len(values)):
            if pick and abs(values[i] - pick[-1]) < gap:
                continue
            pick.append(values[i])
            out.append(sorted(pick))
            walk(i + 1)
            pick.pop()

    walk(0)
    return sorted(out)

from itertools import combinations

def spaced_picks(values, gap):
    strikes = sorted(values)
    out = []
    for size in range(1, len(strikes) + 1):
        for pick in combinations(strikes, size):
            if all(b - a >= gap for a, b in zip(pick, pick[1:])):
                out.append(list(pick))
    return out
